#!/usr/bin/env python3
import sys
from pwn import *
context.log_level = 'error'

LOCAL = '--local' in sys.argv
def connect():
    if LOCAL:
        return process('./guard-dog-local2', cwd='/home/ctfplayer/workspace')
    return remote('diamond-dogs.chal.csaw.io', 1025)

def rest(p):
    return p.recvuntil(b'> ', timeout=3)

def adopt(p, k, name=b'x'):
    p.sendline(b'1'); rest(p)
    p.sendline(str(k).encode()); rest(p)
    p.send(name.ljust(0x18, b'\0') + b'\n')
    return rest(p)

def release(p, k):
    p.sendline(b'3'); rest(p)
    p.sendline(str(k).encode())
    return rest(p)

def command(p, k):
    p.sendline(b'2'); rest(p)
    p.sendline(str(k).encode())
    return rest(p)

def note(p, k, size, data):
    p.sendline(b'4'); rest(p)
    p.sendline(str(k).encode()); rest(p)
    p.sendline(str(size).encode())
    # this is the one with the size prompt; locate it experimentally
    d = rest(p)
    return d, p

if LOCAL:
    p = connect()
else:
    p = connect()
d = rest(p)
print('boot:', repr(d[-30:]))

# adopt 0
p.sendline(b'1'); d = rest(p); print('after 1 (kennel?):', repr(d[-60:]))
p.sendline(b'0'); d = rest(p); print('after 0 (name?):', repr(d[-60:]))
p.send(b'A' * 0x18 + b'\n')
d = rest(p); print('after name:', repr(d[-40:]))

# note 0 size 32
p.sendline(b'4'); d = rest(p); print('after 4:', repr(d[-60:]))
p.sendline(b'0'); d = rest(p); print('after 0:', repr(d[-60:]))
p.sendline(b'32'); d = rest(p); print('after 32:', repr(d[-60:]))
p.send(b'B' * 32)
d = rest(p); print('after contents:', repr(d[-40:]))

# read 0
p.sendline(b'5'); d = rest(p); print('after 5:', repr(d[-60:]))
p.sendline(b'0'); d = rest(p); print('after 0:', repr(d[:200]))
p.close()

#!/usr/bin/env python3
# Diamond Dogs helpers. Verified prompts (local run):
#   menu tail: "6) shred note\n7) go home\n> "
#   adopt:  "kennel (0-7): " then "name: "
#   note:   "note slot (0-7): " then "size: " then "contents: "
#   read:   "note slot: contents: " + payload + "\n" + menu
#   read:   "note slot: bad slot\n"
from pwn import *
import sys

context.arch = 'amd64'
context.log_level = 'error'
HOST, PORT = 'diamond-dogs.chal.csaw.io', 1025
MENU = b'7) go home\n> '

def connect(local=False):
    if local:
        return process('./guard-dog-local2', cwd='/home/ctfplayer/workspace')
    return remote(HOST, PORT)

def menu(p, choice, wait=MENU):
    p.sendline(str(choice).encode())
    return p.recvuntil(wait, timeout=5)

def adopt(p, k, name=b'x'):
    menu(p, 1)
    p.sendline(str(k).encode())
    p.recvuntil(b'name: ', timeout=5)
    p.send(name.ljust(0x18, b'\0') + b'\n')
    return p.recvuntil(MENU, timeout=5)

def release(p, k):
    menu(p, 3)
    p.sendline(str(k).encode())
    return p.recvuntil(MENU, timeout=5)

def command(p, k):
    menu(p, 2)
    p.sendline(str(k).encode())
    return p.recvuntil(MENU, timeout=5)

def note(p, k, size, data):
    menu(p, 4)
    p.sendline(str(k).encode())
    p.recvuntil(b'size: ', timeout=5)
    p.sendline(str(size).encode())
    p.recvuntil(b'contents: ', timeout=5)
    p.send(data)
    return p.recvuntil(MENU, timeout=5)

def readnote(p, k):
    menu(p, 5)
    p.sendline(str(k).encode())
    return p.recvuntil(MENU, timeout=5)

def shred(p, k):
    menu(p, 6)
    p.sendline(str(k).encode())
    return p.recvuntil(MENU, timeout=5)

